package main
import "fmt"

func binominal(n int, k int) int{
    if k == 0{
        return 1
    }

    if k == n {
        return 1
    }

    return binominal(n - 1, k - 1) + binominal(n-1, k)
}
func main() {

    var n, k int

    fmt.Scan(&n, &k)

    fmt.Println(binominal(n, k))
}
